('Spark Football Academy (Spark Turf)', 'sports', 'Chennai', 'Puzhuthivakkam', 1, NULL, NULL, array['Football','Turf Rental','Kids Academy'], 'Box turf ground with locker rooms, parking, and a youth football academy. ₹800/hour weekdays, ₹1,000/hour weekends for 8 players.', true),
